text:
isfold-gap0 : (m : ℕ) → (n : ℕ) → {p : ℕ} → fold p (_+_ n) (suc m) ≡ suc m * n + p
2 clause(s), 2 step(s), lemmas: add-suc-dist, mul-succ

clause isfold-gap0 0 n {p}
  goal: fold p (_+_ n) 1 ≡ 1 * n + p
  1. fold p (_+_ n) 1 ≡ 1 * n + p
       by {!!}

clause isfold-gap0 (suc m) n {p}
  goal: fold p (_+_ n) (suc (suc m)) ≡ suc (suc m) * n + p
  1. fold p (_+_ n) (suc (suc m)) ≡ suc (suc m) * n + p
       by {!!}

lemmas used:
  add-suc-dist : (m : ℕ) {n = n₁ : ℕ} (k : ℕ) → m + n₁ + k ≡ m + (n₁ + k)
  mul-succ : (m : ℕ) {n = n₁ : ℕ} → suc m * n₁ ≡ suc m * n₁
